CREATE TABLE "Session" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "familyId" UUID NOT NULL, "tokenHash" VARCHAR(64) NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "replacedByTokenId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" UUID NOT NULL, "spaId" UUID, "actorUserId" UUID, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "ipAddress" TEXT, "userAgent" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SpaService" ("id" UUID NOT NULL, "spaId" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "durationMinutes" INTEGER NOT NULL, "price" DECIMAL(12,2) NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SpaService_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProfessionalService" ("spaId" UUID NOT NULL, "professionalId" UUID NOT NULL, "serviceId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProfessionalService_pkey" PRIMARY KEY ("professionalId", "serviceId"));
CREATE TABLE "ProfessionalSchedule" ("id" UUID NOT NULL, "spaId" UUID NOT NULL, "professionalId" UUID NOT NULL, "dayOfWeek" INTEGER NOT NULL, "startMinute" INTEGER NOT NULL, "endMinute" INTEGER NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProfessionalSchedule_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Session_familyId_idx" ON "Session"("familyId");
CREATE INDEX "AuditLog_spaId_createdAt_idx" ON "AuditLog"("spaId", "createdAt");
CREATE INDEX "AuditLog_actorUserId_createdAt_idx" ON "AuditLog"("actorUserId", "createdAt");
CREATE UNIQUE INDEX "SpaService_id_spaId_key" ON "SpaService"("id", "spaId");
CREATE UNIQUE INDEX "SpaService_spaId_name_key" ON "SpaService"("spaId", "name");
CREATE INDEX "SpaService_spaId_idx" ON "SpaService"("spaId");
CREATE INDEX "ProfessionalService_spaId_idx" ON "ProfessionalService"("spaId");
CREATE UNIQUE INDEX "ProfessionalSchedule_id_spaId_key" ON "ProfessionalSchedule"("id", "spaId");
CREATE UNIQUE INDEX "ProfessionalSchedule_professionalId_dayOfWeek_startMinute_endMinute_key" ON "ProfessionalSchedule"("professionalId", "dayOfWeek", "startMinute", "endMinute");
CREATE INDEX "ProfessionalSchedule_spaId_professionalId_dayOfWeek_idx" ON "ProfessionalSchedule"("spaId", "professionalId", "dayOfWeek");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_spaId_fkey" FOREIGN KEY ("spaId") REFERENCES "Spa"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SpaService" ADD CONSTRAINT "SpaService_spaId_fkey" FOREIGN KEY ("spaId") REFERENCES "Spa"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProfessionalService" ADD CONSTRAINT "ProfessionalService_professionalId_spaId_fkey" FOREIGN KEY ("professionalId", "spaId") REFERENCES "Professional"("id", "spaId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProfessionalService" ADD CONSTRAINT "ProfessionalService_serviceId_spaId_fkey" FOREIGN KEY ("serviceId", "spaId") REFERENCES "SpaService"("id", "spaId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProfessionalSchedule" ADD CONSTRAINT "ProfessionalSchedule_spaId_fkey" FOREIGN KEY ("spaId") REFERENCES "Spa"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProfessionalSchedule" ADD CONSTRAINT "ProfessionalSchedule_professionalId_spaId_fkey" FOREIGN KEY ("professionalId", "spaId") REFERENCES "Professional"("id", "spaId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProfessionalSchedule" ADD CONSTRAINT "ProfessionalSchedule_dayOfWeek_check" CHECK ("dayOfWeek" BETWEEN 0 AND 6);
ALTER TABLE "ProfessionalSchedule" ADD CONSTRAINT "ProfessionalSchedule_minutes_check" CHECK ("startMinute" >= 0 AND "endMinute" <= 1440 AND "startMinute" < "endMinute");
